modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.ChuaCircuit;
end Baseline;
model BUG012
  extends Modelica.Electrical.Analog.Examples.ChuaCircuit(L(L=0));
end BUG012;
model BUG013
  extends Modelica.Electrical.Analog.Examples.ChuaCircuit(C1(C=0));
end BUG013;
model BUG014
  extends Modelica.Electrical.Analog.Examples.ChuaCircuit(C2(C=0));
end BUG014;
model FinalBUG012
  extends Modelica.Electrical.Analog.Examples.ChuaCircuit(L(final L=0));
end FinalBUG012;
model FinalBUG013
  extends Modelica.Electrical.Analog.Examples.ChuaCircuit(C1(final C=0));
end FinalBUG013;
model FinalBUG014
  extends Modelica.Electrical.Analog.Examples.ChuaCircuit(C2(final C=0));
end FinalBUG014;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG012\n");
simulate(BUG012, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG013\n");
simulate(BUG013, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG014\n");
simulate(BUG014, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG012\n");
simulate(FinalBUG012, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG013\n");
simulate(FinalBUG013, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG014\n");
simulate(FinalBUG014, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG012\n");
system("./Baseline -override L.L=0 -r=BUG012_override.csv");
print("AUDIT_OVERRIDE BUG013\n");
system("./Baseline -override C1.C=0 -r=BUG013_override.csv");
print("AUDIT_OVERRIDE BUG014\n");
system("./Baseline -override C2.C=0 -r=BUG014_override.csv");
